**Source:** Extracted from Backend Specialist SQL Injection Prevention patterns

**Vulnerability Pattern:**
```typescript
// VULNERABLE CODE
const query = `SELECT * FROM users WHERE email = '${userEmail}'`;
const result = await db.query(query);
```

**Automated Fix:**
```typescript
// SECURE CODE - Parameterized Query
const query = 'SELECT * FROM users WHERE email = $1';
const result = await db.query(query, [userEmail]);
```

**Full Remediation Function:**

```typescript
// fix_sql_injection.ts
import { parse, print } from 'recast';
import * as types from 'ast-types';

function fixSQLInjection(code: string): string {
  const ast = parse(code);

  // Find vulnerable string concatenation in SQL queries
  types.visit(ast, {
    visitCallExpression(path) {
      const node = path.node;

      // Check if it's a database query call
      if (
        node.callee.type === 'MemberExpression' &&
        node.callee.property.name === 'query' &&
        node.arguments.length > 0
      ) {
        const firstArg = node.arguments[0];

        // Check if query uses template literal or string concatenation
        if (firstArg.type === 'TemplateLiteral' || firstArg.type === 'BinaryExpression') {
          console.log('FIXING SQL Injection vulnerability');

          // Convert to parameterized query
          const parameterizedQuery = convertToParameterized(firstArg);

          // Replace with secure version
          node.arguments[0] = parameterizedQuery.query;
          node.arguments[1] = parameterizedQuery.params;
        }
      }

      this.traverse(path);
    }
  });

  return print(ast).code;
}

function convertToParameterized(node: any): { query: any, params: any } {
  // Extract variables from template literal
  const variables: string[] = [];
  let queryString = '';

  if (node.type === 'TemplateLiteral') {
    let paramCounter = 1;

    node.quasis.forEach((quasi: any, index: number) => {
      queryString += quasi.value.raw;

      if (node.expressions[index]) {
        variables.push(node.expressions[index]);
        queryString += `$${paramCounter++}`;
      }
    });
  }

  return {
    query: types.builders.literal(queryString),
    params: types.builders.arrayExpression(variables)
  };
}

// Example usage
const vulnerableCode = `
const email = req.body.email;
const query = \`SELECT * FROM users WHERE email = '\${email}'\`;
const result = await db.query(query);
`;

const secureCode = fixSQLInjection(vulnerableCode);
console.log(secureCode);
/*
Output:
const email = req.body.email;
const query = 'SELECT * FROM users WHERE email = $1';
const result = await db.query(query, [email]);
*/
```

**Source:** Research-added (secure coding practices)

```typescript
// BEFORE: Raw SQL (vulnerable)
const getUserByEmail = async (email: string) => {
  const query = `SELECT * FROM users WHERE email = '${email}'`;
  return await db.query(query);
};

// AFTER: Prisma ORM (type-safe, injection-proof)
import { PrismaClient } from '@prisma/client';
const prisma = new PrismaClient();

const getUserByEmail = async (email: string) => {
  return await prisma.user.findUnique({
    where: { email }
  });
};

// AFTER: Supabase (parameterized by default)
import { supabase } from '@/lib/supabase';

const getUserByEmail = async (email: string) => {
  const { data, error } = await supabase
    .from('users')
    .select('*')
    .eq('email', email)  // Automatically parameterized
    .single();

  return data;
};
```

**Source:** Extracted from Backend Specialist + Research-added

```typescript
// Add validation before database queries
import { z } from 'zod';

const searchSchema = z.object({
  query: z.string()
    .min(1, 'Query is required')
    .max(100, 'Query too long')
    .regex(/^[a-zA-Z0-9\s]+$/, 'Only alphanumeric characters allowed'),
  limit: z.number().int().min(1).max(100).optional()
});

// BEFORE: No validation
app.get('/search', async (req, res) => {
  const { query } = req.query;
  const results = await db.query(`SELECT * FROM products WHERE name LIKE '%${query}%'`);
  res.json(results);
});

// AFTER: Validation + Parameterization
app.get('/search', async (req, res) => {
  try {
    // Validate input
    const { query, limit = 10 } = searchSchema.parse(req.query);

    // Parameterized query
    const results = await db.query(
      'SELECT * FROM products WHERE name LIKE $1 LIMIT $2',
      [`%${query}%`, limit]
    );

    res.json(results);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return res.status(400).json({ error: 'Invalid input', details: error.errors });
    }
    throw error;
  }
});
```

**Best Practices:**
- ✅ DO: Use parameterized queries for ALL database operations
- ✅ DO: Migrate to ORMs (Prisma, TypeORM) for type safety
- ✅ DO: Validate input with schema validation (Zod)
- ✅ DO: Use stored procedures for complex queries
- ✅ DO: Apply principle of least privilege to database users
- ❌ DON'T: Trust any user input
- ❌ DON'T: Use string concatenation in SQL queries

