```typescript
// Implement strict CSP to prevent XSS execution
import helmet from 'helmet';

app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: [
        "'self'",
        // Use nonces for inline scripts (no 'unsafe-inline')
        (req, res) => `'nonce-${res.locals.cspNonce}'`
      ],
      styleSrc: ["'self'", "'unsafe-inline'"],  // Consider using nonces here too
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'", "https://api.yourdomain.com"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"]
    }
  })
);

// Nonce middleware
app.use((req, res, next) => {
  res.locals.cspNonce = crypto.randomBytes(16).toString('base64');
  next();
});

// In HTML template
// <script nonce="<%= cspNonce %>">
//   // Inline script here
// </script>
```

**Source:** Research-added

```tsx
// React automatically escapes by default, but be careful with:

// VULNERABLE: dangerouslySetInnerHTML
function UserComment({ comment }) {
  return <div dangerouslySetInnerHTML={{ __html: comment }} />;  // XSS!
}

// SAFE: Let React escape automatically
function UserComment({ comment }) {
  return <div>{comment}</div>;  // Automatically escaped
}

// SAFE: Sanitize with DOMPurify if HTML needed
import DOMPurify from 'dompurify';

function UserComment({ comment }) {
  const sanitizedHTML = DOMPurify.sanitize(comment, {
    ALLOWED_TAGS: ['b', 'i', 'em', 'strong', 'a'],
    ALLOWED_ATTR: ['href']
  });

  return <div dangerouslySetInnerHTML={{ __html: sanitizedHTML }} />;
}
```

**Best Practices:**
- ✅ DO: Use template engines with auto-escaping (EJS, Handlebars)
- ✅ DO: Implement Content Security Policy
- ✅ DO: Sanitize HTML with DOMPurify if needed
- ✅ DO: Validate and encode all user input
- ❌ DON'T: Use dangerouslySetInnerHTML without sanitization
- ❌ DON'T: Allow 'unsafe-inline' in CSP script-src

