**Source:** Extracted from Backend Specialist JWT patterns

```typescript
// BEFORE: Weak secret
const JWT_SECRET = "secret";  // CRITICAL VULNERABILITY

// AFTER: Strong secret (32+ bytes)
import crypto from 'crypto';

// Generate strong secret (run once, save to .env)
const JWT_SECRET = crypto.randomBytes(32).toString('hex');
console.log('JWT_SECRET=' + JWT_SECRET);
// Output: JWT_SECRET=a4f8b2c9d1e7f3a0b5c8d2e6f9a1b4c7d0e3f6a9b2c5d8e1f4a7b0c3d6e9f2a5

// Use environment variable
if (!process.env.JWT_SECRET || process.env.JWT_SECRET.length < 32) {
  throw new Error('JWT_SECRET must be at least 32 characters');
}

const JWT_SECRET = process.env.JWT_SECRET;
```

**Source:** Research-added (JWT security best practices)

```typescript
// BEFORE: Accepts any algorithm
export function verifyToken(token: string) {
  return jwt.verify(token, JWT_SECRET);  // Vulnerable to algorithm confusion
}

// AFTER: Explicit algorithm validation
export function verifyToken(token: string) {
  return jwt.verify(token, JWT_SECRET, {
    algorithms: ['HS256'],  // Explicitly only allow HS256
    issuer: 'your-app',
    audience: 'your-app-users'
  });
}

// For RS256 (asymmetric), verify algorithm matches
export function verifyTokenRS256(token: string, publicKey: string) {
  const decoded = jwt.decode(token, { complete: true });

  // Verify algorithm before verification
  if (decoded?.header.alg !== 'RS256') {
    throw new Error('Invalid token algorithm');
  }

  return jwt.verify(token, publicKey, {
    algorithms: ['RS256'],
    issuer: 'your-app'
  });
}
```

**Source:** Extracted from Backend Specialist

```typescript
// BEFORE: No expiration or long expiration
const token = jwt.sign(payload, JWT_SECRET);  // Never expires!

// AFTER: Short-lived access tokens + refresh tokens
const ACCESS_TOKEN_EXPIRY = '15m';  // 15 minutes
const REFRESH_TOKEN_EXPIRY = '7d';   // 7 days

export function generateAccessToken(payload: TokenPayload): string {
  return jwt.sign(payload, JWT_SECRET, {
    expiresIn: ACCESS_TOKEN_EXPIRY,
    algorithm: 'HS256',
    issuer: 'your-app',
    subject: payload.userId,
    jwtid: crypto.randomUUID()  // Unique token ID for tracking
  });
}

export function generateRefreshToken(payload: TokenPayload): string {
  return jwt.sign(
    { userId: payload.userId, type: 'refresh' },
    REFRESH_TOKEN_SECRET,
    {
      expiresIn: REFRESH_TOKEN_EXPIRY,
      algorithm: 'HS256'
    }
  );
}
```

**Source:** Research-added

```typescript
// BEFORE: Sensitive data in JWT payload
const token = jwt.sign({
  userId: user.id,
  email: user.email,
  password: user.password,  // CRITICAL: Password in JWT!
  ssn: user.ssn,            // CRITICAL: SSN in JWT!
  creditCard: user.creditCard  // CRITICAL: Credit card in JWT!
}, JWT_SECRET);

// AFTER: Only non-sensitive data
const token = jwt.sign({
  userId: user.id,
  email: user.email,
  role: user.role,
  // No passwords, SSN, credit cards, API keys, etc.
}, JWT_SECRET, {
  expiresIn: '15m'
});
```

**Best Practices:**
- ✅ DO: Use strong secrets (32+ bytes, stored in env vars)
- ✅ DO: Validate algorithm explicitly
- ✅ DO: Use short-lived access tokens (15 min)
- ✅ DO: Implement refresh token rotation
- ✅ DO: Use RS256 for distributed systems
- ❌ DON'T: Store sensitive data in JWT payload
- ❌ DON'T: Accept 'none' algorithm
- ❌ DON'T: Use weak secrets ('secret', 'password')

