**Source:** Extracted from Security Auditor findings

```typescript
// BEFORE: No ownership check (IDOR vulnerable)
app.get('/api/users/:userId/profile', authenticate, async (req, res) => {
  const profile = await db.users.findOne({ id: req.params.userId });
  res.json(profile);  // Any authenticated user can access any profile!
});

// AFTER: Ownership validation
app.get('/api/users/:userId/profile', authenticate, async (req, res) => {
  const requestedUserId = req.params.userId;
  const authenticatedUserId = req.user.id;
  const userRole = req.user.role;

  // Check ownership or admin role
  if (requestedUserId !== authenticatedUserId && userRole !== 'admin') {
    return res.status(403).json({
      error: 'Forbidden',
      message: 'You can only access your own profile'
    });
  }

  const profile = await db.users.findOne({ id: requestedUserId });
  res.json(profile);
});
```

**Source:** Research-added (OWASP Secure Coding)

```typescript
// rbac_middleware.ts
import { NextRequest, NextResponse } from 'next/server';

type Permission = 'user:read' | 'user:write' | 'user:delete' | 'admin:all';

interface RolePermissions {
  [key: string]: Permission[];
}

const ROLE_PERMISSIONS: RolePermissions = {
  guest: ['user:read'],
  user: ['user:read', 'user:write'],
  admin: ['user:read', 'user:write', 'user:delete', 'admin:all']
};

export function requirePermission(...permissions: Permission[]) {
  return async (req: NextRequest) => {
    const userRole = req.headers.get('x-user-role');

    if (!userRole) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const userPermissions = ROLE_PERMISSIONS[userRole] || [];

    const hasPermission = permissions.every(permission =>
      userPermissions.includes(permission) || userPermissions.includes('admin:all')
    );

    if (!hasPermission) {
      return NextResponse.json({
        error: 'Forbidden',
        message: `Required permissions: ${permissions.join(', ')}`
      }, { status: 403 });
    }

    return NextResponse.next();
  };
}

// Usage
import { requirePermission } from '@/middleware/rbac';

export async function DELETE(req: NextRequest) {
  const permissionCheck = await requirePermission('user:delete')(req);
  if (permissionCheck.status !== 200) {
    return permissionCheck;
  }

  // Proceed with delete
  const userId = req.url.split('/').pop();
  await db.users.delete({ id: userId });

  return NextResponse.json({ success: true });
}
```

**Source:** Extracted from Backend Specialist

```typescript
// lib/auth/ownership.ts
import { createAdminClient } from '@/lib/supabase/admin';

export async function verifyResourceOwnership(
  userId: string,
  resourceType: 'project' | 'post' | 'comment',
  resourceId: string
): Promise<boolean> {
  const supabase = createAdminClient();

  const { data, error } = await supabase
    .from(resourceType + 's')  // projects, posts, comments
    .select('user_id')
    .eq('id', resourceId)
    .single();

  if (error || !data) {
    return false;
  }

  return data.user_id === userId;
}

// Usage in API route
app.delete('/api/posts/:postId', authenticate, async (req, res) => {
  const { postId } = req.params;
  const userId = req.user.id;

  // Verify ownership
  const isOwner = await verifyResourceOwnership(userId, 'post', postId);

  if (!isOwner && req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  await db.posts.delete({ id: postId });
  res.json({ success: true });
});
```

**Best Practices:**
- ✅ DO: Always validate resource ownership
- ✅ DO: Implement role-based access control
- ✅ DO: Use middleware for permission checks
- ✅ DO: Check authorization on EVERY endpoint
- ✅ DO: Fail securely (deny by default)
- ❌ DON'T: Trust client-side checks
- ❌ DON'T: Expose internal IDs without authorization

