**Source:** Research-added

```sql
-- Function to test RLS policies as different users
CREATE OR REPLACE FUNCTION test_rls_policy(
  test_user_id UUID,
  test_table_name TEXT
) RETURNS TABLE(can_select BOOLEAN, can_insert BOOLEAN, can_update BOOLEAN, can_delete BOOLEAN) AS $$
BEGIN
  -- Set user context
  PERFORM set_config('request.jwt.claims', json_build_object('sub', test_user_id)::text, true);

  -- Test SELECT
  BEGIN
    EXECUTE format('SELECT 1 FROM %I LIMIT 1', test_table_name);
    can_select := true;
  EXCEPTION WHEN OTHERS THEN
    can_select := false;
  END;

  -- Test INSERT
  BEGIN
    EXECUTE format('INSERT INTO %I DEFAULT VALUES', test_table_name);
    can_insert := true;
    ROLLBACK;
  EXCEPTION WHEN OTHERS THEN
    can_insert := false;
  END;

  -- Test UPDATE
  BEGIN
    EXECUTE format('UPDATE %I SET updated_at = NOW() WHERE user_id = %L', test_table_name, test_user_id);
    can_update := true;
    ROLLBACK;
  EXCEPTION WHEN OTHERS THEN
    can_update := false;
  END;

  -- Test DELETE
  BEGIN
    EXECUTE format('DELETE FROM %I WHERE user_id = %L', test_table_name, test_user_id);
    can_delete := true;
    ROLLBACK;
  EXCEPTION WHEN OTHERS THEN
    can_delete := false;
  END;

  RETURN QUERY SELECT can_select, can_insert, can_update, can_delete;
END;
$$ LANGUAGE plpgsql;

-- Usage
SELECT * FROM test_rls_policy('user-a-id'::UUID, 'posts');
```

**Best Practices:**
- ✅ DO: Use EXISTS instead of IN for better performance
- ✅ DO: Add indexes on RLS policy columns
- ✅ DO: Test RLS policies with multiple user roles
- ✅ DO: Include soft delete checks in RLS
- ✅ DO: Separate policies for different roles
- ❌ DON'T: Rely solely on user_metadata (user-modifiable)
- ❌ DON'T: Forget to test RLS policy performance

