**Source:** Extracted from Backend Specialist CORS patterns

```typescript
// BEFORE: Wildcard CORS (vulnerable)
app.use(cors());  // Allows ALL origins

// AFTER: Explicit whitelist
import cors from 'cors';

const ALLOWED_ORIGINS = [
  'https://app.yourdomain.com',
  'https://admin.yourdomain.com',
  process.env.NODE_ENV === 'development' ? 'http://localhost:3000' : null
].filter(Boolean);

app.use(cors({
  origin: (origin, callback) => {
    if (!origin || ALLOWED_ORIGINS.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400  // 24 hours
}));
```

**Source:** Research-added

```typescript
// .env.production
ALLOWED_ORIGINS=https://app.yourdomain.com,https://admin.yourdomain.com

// .env.development
ALLOWED_ORIGINS=http://localhost:3000,http://localhost:3001

// cors.config.ts
function getAllowedOrigins(): string[] {
  const origins = process.env.ALLOWED_ORIGINS;

  if (!origins) {
    throw new Error('ALLOWED_ORIGINS environment variable not set');
  }

  return origins.split(',').map(origin => origin.trim());
}

export const corsOptions = {
  origin: (origin: string | undefined, callback: (err: Error | null, allow?: boolean) => void) => {
    const allowedOrigins = getAllowedOrigins();

    if (!origin) {
      // Allow requests with no origin (mobile apps, curl, Postman)
      callback(null, true);
      return;
    }

    if (allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn('CORS violation', { origin, allowed: allowedOrigins });
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true
};
```

**Best Practices:**
- ✅ DO: Use explicit origin whitelist
- ✅ DO: Store allowed origins in environment variables
- ✅ DO: Set credentials: true only with explicit origins
- ✅ DO: Log CORS violations
- ✅ DO: Use different origins for dev/staging/prod
- ❌ DON'T: Use wildcard (*) in production
- ❌ DON'T: Reflect arbitrary origins

