// security_headers.test.ts
import { test, expect } from '@playwright/test';

test('should have all required security headers', async ({ page }) => {
  const response = await page.goto('https://example.com');

  const headers = response?.headers() || {};

  // Content Security Policy
  expect(headers['content-security-policy']).toBeDefined();
  expect(headers['content-security-policy']).toContain("default-src 'self'");

  // HSTS
  expect(headers['strict-transport-security']).toBeDefined();
  expect(headers['strict-transport-security']).toContain('max-age=31536000');

  // X-Frame-Options
  expect(headers['x-frame-options']).toMatch(/^(DENY|SAMEORIGIN)$/);

  // X-Content-Type-Options
  expect(headers['x-content-type-options']).toBe('nosniff');

  // Referrer-Policy
  expect(headers['referrer-policy']).toBeDefined();
});
```

**Best Practices:**
- ✅ DO: Write automated tests for all security fixes
- ✅ DO: Test with malicious payloads
- ✅ DO: Verify fix doesn't break functionality
- ✅ DO: Run tests in CI/CD pipeline
- ✅ DO: Test both positive and negative cases
- ❌ DON'T: Deploy fixes without verification
- ❌ DON'T: Skip regression testing

