```typescript
// BEFORE: Unsafe URL fetching
app.post('/api/fetch', async (req, res) => {
  const { url } = req.body;
  const response = await fetch(url);  // SSRF Vulnerable!
  res.json(await response.json());
});

// AFTER: URL whitelist with validation
import { URL } from 'url';
import { isIP } from 'net';

const ALLOWED_DOMAINS = [
  'api.example.com',
  'cdn.example.com',
  'assets.example.com'
];

const BLOCKED_IPS = [
  '127.0.0.1', 'localhost', '0.0.0.0',
  /^10\./, /^172\.(1[6-9]|2[0-9]|3[01])\./, /^192\.168\./,
  '169.254.169.254', 'metadata.google.internal'
];

function isAllowedURL(urlString: string): boolean {
  try {
    const url = new URL(urlString);

    // Only allow HTTP/HTTPS
    if (!['http:', 'https:'].includes(url.protocol)) {
      return false;
    }

    // Check against blocked IPs
    for (const blocked of BLOCKED_IPS) {
      if (typeof blocked === 'string' && url.hostname === blocked) {
        return false;
      }
      if (blocked instanceof RegExp && blocked.test(url.hostname)) {
        return false;
      }
    }

    // Check if hostname is an IP (block direct IP access)
    if (isIP(url.hostname)) {
      return false;
    }

    // Whitelist check
    return ALLOWED_DOMAINS.includes(url.hostname);

  } catch {
    return false;
  }
}

app.post('/api/fetch', async (req, res) => {
  const { url } = req.body;

  if (!isAllowedURL(url)) {
    return res.status(400).json({ error: 'URL not allowed' });
  }

  const response = await fetch(url);
  res.json(await response.json());
});
