```typescript
// BEFORE: Vulnerable to prototype pollution
function merge(target: any, source: any) {
  for (const key in source) {
    if (typeof source[key] === 'object') {
      target[key] = merge(target[key] || {}, source[key]);
    } else {
      target[key] = source[key];  // __proto__ can be set!
    }
  }
  return target;
}

// AFTER: Safe merge with blocked keys
const BLOCKED_KEYS = ['__proto__', 'constructor', 'prototype'];

function safeMerge(target: any, source: any): any {
  if (source === null || typeof source !== 'object') {
    return source;
  }

  const result = { ...target };

  for (const key of Object.keys(source)) {
    // Block prototype pollution vectors
    if (BLOCKED_KEYS.includes(key)) {
      continue;
    }

    if (typeof source[key] === 'object' && source[key] !== null) {
      result[key] = safeMerge(result[key] || {}, source[key]);
    } else {
      result[key] = source[key];
    }
  }

  return result;
}

// Additional: Freeze objects to prevent modification
const config = Object.freeze({
  apiUrl: process.env.API_URL,
  maxLimit: 100
});

// Use Object.create(null) for pure data objects
const userData = Object.create(null);
userData.name = userInput;  // No prototype chain to pollute
