// BEFORE: No password requirements
const passwordSchema = z.string();

// AFTER: Strong password policy with Zod
import { z } from 'zod';

const passwordSchema = z.string()
  .min(8, 'Password must be at least 8 characters')
  .max(128, 'Password must be less than 128 characters')
  .regex(/[A-Z]/, 'Must contain at least one uppercase letter')
  .regex(/[a-z]/, 'Must contain at least one lowercase letter')
  .regex(/[0-9]/, 'Must contain at least one number')
  .regex(/[^A-Za-z0-9]/, 'Must contain at least one special character')
  .refine(
    (password) => !commonPasswords.includes(password.toLowerCase()),
    'This password is too common. Please choose a stronger password.'
  );

// Common passwords list (abbreviated)
const commonPasswords = [
  'password', 'password123', '12345678', 'qwerty', 'letmein',
  'welcome', 'admin', 'login', 'passw0rd', 'master'
];

// Usage
try {
  passwordSchema.parse(userPassword);
} catch (error) {
  if (error instanceof z.ZodError) {
    return res.status(400).json({
      error: 'Password requirements not met',
      details: error.errors.map(e => e.message)
    });
  }
