```typescript
// BEFORE: Session fixation vulnerable
app.post('/login', async (req, res) => {
  const user = await authenticate(req.body.email, req.body.password);
  req.session.userId = user.id;  // Same session ID!
  res.json({ success: true });
});

// AFTER: Regenerate session on login
app.post('/login', async (req, res) => {
  const user = await authenticate(req.body.email, req.body.password);

  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Regenerate session to prevent fixation
  req.session.regenerate((err) => {
    if (err) {
      return res.status(500).json({ error: 'Session error' });
    }

    req.session.userId = user.id;
    req.session.loginTime = Date.now();

    req.session.save((err) => {
      if (err) {
        return res.status(500).json({ error: 'Session save error' });
      }

      res.json({ success: true });
    });
  });
});

// For JWT-based auth, invalidate old refresh tokens
async function loginWithTokenRotation(userId: string) {
  // Invalidate all existing refresh tokens for this user
  await db.refreshTokens.deleteMany({ userId });

  // Generate new token family
  const familyId = crypto.randomUUID();
  const accessToken = generateAccessToken({ userId });
  const refreshToken = generateRefreshToken({ userId, familyId });

  // Store new refresh token
  await db.refreshTokens.create({
    userId,
    familyId,
    tokenHash: hashToken(refreshToken),
    expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000)
  });

  return { accessToken, refreshToken };
}
