// Automated dependency update with lockfile
// scripts/update-dependencies.ts
import { execSync } from 'child_process';

async function secureDependencyUpdate() {
  console.log('Checking for security vulnerabilities...');

  try {
    // Run audit
    execSync('npm audit --json > audit-report.json', { stdio: 'pipe' });
  } catch (error) {
    // npm audit exits with non-zero if vulnerabilities found
  }

  const auditReport = require('./audit-report.json');
  const vulnerabilities = auditReport.metadata?.vulnerabilities || {};

  if (vulnerabilities.critical > 0 || vulnerabilities.high > 0) {
    console.log('Critical/High vulnerabilities found. Attempting fix...');

    execSync('npm audit fix', { stdio: 'inherit' });

    // Verify fix
    execSync('npm audit --audit-level=high');

    console.log('Vulnerabilities fixed successfully.');
  } else {
    console.log('No critical vulnerabilities found.');
  }
}

secureDependencyUpdate();
