```typescript
// BEFORE: No rate limiting
export async function POST(request: NextRequest) {
  const { email, password } = await request.json()
  const user = await authenticate(email, password)
  return NextResponse.json({ token: generateToken(user) })
}

// AFTER: Rate limiting with Upstash Redis
import { Ratelimit } from '@upstash/ratelimit'
import { Redis } from '@upstash/redis'
import { NextRequest, NextResponse } from 'next/server'

// Create rate limiters for different endpoints
const authLimiter = new Ratelimit({
  redis: new Redis({
    url: process.env.UPSTASH_REDIS_REST_URL!,
    token: process.env.UPSTASH_REDIS_REST_TOKEN!
  }),
  limiter: Ratelimit.slidingWindow(5, '15 m'), // 5 requests per 15 minutes
  analytics: true,
  prefix: 'ratelimit:auth'
})

const apiLimiter = new Ratelimit({
  redis: new Redis({
    url: process.env.UPSTASH_REDIS_REST_URL!,
    token: process.env.UPSTASH_REDIS_REST_TOKEN!
  }),
  limiter: Ratelimit.slidingWindow(100, '1 m'), // 100 requests per minute
  analytics: true,
  prefix: 'ratelimit:api'
})

export async function withRateLimit(
  request: NextRequest,
  limiter: Ratelimit
): Promise<NextResponse | null> {
  // Get identifier (IP or user ID)
  const ip = request.headers.get('x-forwarded-for') ||
             request.headers.get('x-real-ip') ||
             'unknown'

  const { success, limit, reset, remaining } = await limiter.limit(ip)

  if (!success) {
    // Log rate limit event
    await logSecurityEvent({
      type: 'RATE_LIMIT_EXCEEDED',
      ip,
      userAgent: request.headers.get('user-agent') || '',
      details: { limit, reset }
    })

    return NextResponse.json(
      {
        error: 'Too many requests',
        retryAfter: Math.ceil((reset - Date.now()) / 1000)
      },
      {
        status: 429,
        headers: {
          'X-RateLimit-Limit': limit.toString(),
          'X-RateLimit-Remaining': remaining.toString(),
          'X-RateLimit-Reset': reset.toString(),
          'Retry-After': Math.ceil((reset - Date.now()) / 1000).toString()
        }
      }
    )
  }

  return null // No rate limit hit, continue
}

// Usage in auth endpoint
export async function POST(request: NextRequest) {
  // Check rate limit
  const rateLimitResponse = await withRateLimit(request, authLimiter)
  if (rateLimitResponse) return rateLimitResponse

  const { email, password } = await request.json()
  const user = await authenticate(email, password)

  if (!user) {
    return NextResponse.json({ error: 'Invalid credentials' }, { status: 401 })
  }

  return NextResponse.json({ token: generateToken(user) })
}
```

```typescript
// For applications without Redis
import { LRUCache } from 'lru-cache'

interface RateLimitEntry {
  count: number
  resetTime: number
}

const rateLimitCache = new LRUCache<string, RateLimitEntry>({
  max: 10000, // Max entries
  ttl: 15 * 60 * 1000 // 15 minutes
})

export function inMemoryRateLimit(
  key: string,
  limit: number,
  windowMs: number
): { success: boolean; remaining: number; resetTime: number } {
  const now = Date.now()
  const entry = rateLimitCache.get(key)

  if (!entry || now > entry.resetTime) {
    // New window
    const newEntry: RateLimitEntry = {
      count: 1,
      resetTime: now + windowMs
    }
    rateLimitCache.set(key, newEntry)

    return {
      success: true,
      remaining: limit - 1,
      resetTime: newEntry.resetTime
    }
  }

  if (entry.count >= limit) {
    return {
      success: false,
      remaining: 0,
      resetTime: entry.resetTime
    }
  }

  entry.count++
  rateLimitCache.set(key, entry)

  return {
    success: true,
    remaining: limit - entry.count,
    resetTime: entry.resetTime
  }
}
