```typescript
// BEFORE: Insecure file upload
app.post('/upload', upload.single('file'), (req, res) => {
  res.json({ path: req.file.path }) // No validation!
})

// AFTER: Secure file upload with validation
import multer from 'multer'
import path from 'path'
import crypto from 'crypto'
import { fileTypeFromBuffer } from 'file-type'

// Allowed MIME types and extensions
const ALLOWED_TYPES: Record<string, string[]> = {
  'image/jpeg': ['.jpg', '.jpeg'],
  'image/png': ['.png'],
  'image/gif': ['.gif'],
  'image/webp': ['.webp'],
  'application/pdf': ['.pdf']
}

const MAX_FILE_SIZE = 10 * 1024 * 1024 // 10MB

// Secure storage configuration
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, '/secure/uploads') // Not publicly accessible
  },
  filename: (req, file, cb) => {
    // Generate random filename (prevent path traversal)
    const randomName = crypto.randomBytes(32).toString('hex')
    const ext = path.extname(file.originalname).toLowerCase()
    cb(null, `${randomName}${ext}`)
  }
})

// File filter
const fileFilter = async (
  req: Express.Request,
  file: Express.Multer.File,
  cb: multer.FileFilterCallback
) => {
  // Check extension
  const ext = path.extname(file.originalname).toLowerCase()
  const allowedExts = Object.values(ALLOWED_TYPES).flat()

  if (!allowedExts.includes(ext)) {
    return cb(new Error(`File extension ${ext} not allowed`))
  }

  // Check declared MIME type
  if (!Object.keys(ALLOWED_TYPES).includes(file.mimetype)) {
    return cb(new Error(`MIME type ${file.mimetype} not allowed`))
  }

  // Verify extension matches MIME type
  if (!ALLOWED_TYPES[file.mimetype]?.includes(ext)) {
    return cb(new Error('File extension does not match MIME type'))
  }

  cb(null, true)
}

const upload = multer({
  storage,
  fileFilter,
  limits: {
    fileSize: MAX_FILE_SIZE,
    files: 1 // Only one file at a time
  }
})

// Endpoint with additional validation
app.post('/api/upload', authenticate, upload.single('file'), async (req, res) => {
  if (!req.file) {
    return res.status(400).json({ error: 'No file uploaded' })
  }

  // Additional magic number validation
  const buffer = await fs.promises.readFile(req.file.path)
  const detectedType = await fileTypeFromBuffer(buffer)

  if (!detectedType || !Object.keys(ALLOWED_TYPES).includes(detectedType.mime)) {
    // Delete suspicious file
    await fs.promises.unlink(req.file.path)
    return res.status(400).json({ error: 'Invalid file type detected' })
  }

  // Scan for malware (if available)
  // await scanForMalware(req.file.path)

  // Generate secure URL (not direct path)
  const fileId = crypto.randomUUID()
  await db.files.create({
    id: fileId,
    userId: req.user.id,
    originalName: file.originalname,
    storagePath: req.file.path,
    mimeType: detectedType.mime,
    size: req.file.size
  })

  res.json({
    fileId,
    downloadUrl: `/api/files/${fileId}`
  })
})

// Secure file serving (not direct access)
app.get('/api/files/:fileId', authenticate, async (req, res) => {
  const file = await db.files.findUnique({
    where: { id: req.params.fileId }
  })

  if (!file || file.userId !== req.user.id) {
    return res.status(404).json({ error: 'File not found' })
  }

  // Set security headers
  res.setHeader('Content-Disposition', `attachment; filename="${file.originalName}"`)
  res.setHeader('Content-Type', file.mimeType)
  res.setHeader('X-Content-Type-Options', 'nosniff')

  res.sendFile(file.storagePath)
})
